     .page,.fm-list,.fm-sidebar,.drawer-body,.modal-list{overscroll-behavior:contain}

     /* ===== TOPBAR ===== */
     .topbar{height:48px;background:var(--bg2);display:flex;align-items:center;padding:0 12px;gap:8px;border-bottom:1px solid var(--bdr);flex-shrink:0;padding-top:max(0px,env(safe-area-inset-top))}
     .live-dot{width:8px;height:8px;border-radius:50%;background:var(--t3);display:inline-block;margin-left:8px}
     .live-dot.on{background:var(--err);box-shadow:0 0 8px rgba(248,81,73,.6);animation:livepulse 1s infinite}
     @keyframes livepulse{50%{opacity:.3}}
     .live-label{font-size:10px;color:var(--t2);margin-left:4px}
     .live-label.on{color:var(--err)}
     .logo{font-size:16px;font-weight:800;background:linear-gradient(135deg,var(--acc),var(--pur));-webkit-background-clip:text;-webkit-text-fill-color:transparent}
     .logo .hub-ver{font-size:9px;font-weight:600;color:var(--t3);-webkit-text-fill-color:var(--t3);background:none;margin-left:4px;vertical-align:super}
     .topbar-right{margin-left:auto;display:flex;align-items:center;gap:6px}
     .sess-clock{font-size:11px;color:var(--t2);font-family:monospace;padding:4px 8px;border-radius:10px;background:rgba(139,148,158,.08);white-space:nowrap}
     .sess-clock.warn{color:var(--warn);background:rgba(210,153,34,.12)}
     .term-recover{display:none;position:fixed;left:50%;bottom:max(14px,env(safe-area-inset-bottom));transform:translateX(-50%);z-index:300;align-items:center;gap:10px;background:rgba(13,17,23,.94);border:1px solid var(--warn);border-radius:10px;padding:8px 8px 8px 14px;font-size:12px;color:var(--t1);box-shadow:0 8px 24px rgba(0,0,0,.5);max-width:92vw;touch-action:manipulation}
     .term-recover.on{display:flex}
     .term-recover span{line-height:1.4;min-width:0}
     .term-recover b{margin-left:6px;background:var(--acc);color:#0d1117;border-radius:7px;padding:7px 12px;font-weight:700;white-space:nowrap;cursor:pointer}
     .term-recover b:active{opacity:.8}
     .sess-clock.bad{color:var(--err);background:rgba(248,81,73,.12);font-weight:700}
     .access-badge{font-size:11px;padding:4px 10px;border-radius:10px;font-weight:600}
     .access-local{color:var(--ok);background:rgba(63,185,80,.12)}
     .access-remote{color:var(--warn);background:rgba(210,153,34,.12)}
     .tunnel-badge{color:#bc8cff;background:rgba(188,140,255,.12);font-size:11px;padding:4px 10px;border-radius:10px;font-weight:600;cursor:pointer;text-decoration:none}
     .tunnel-url{font-size:10px;color:var(--pur);cursor:pointer;text-decoration:underline;text-underline-offset:2px}
     .btn{padding:8px 14px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg4);color:var(--t1);font-size:14px;cursor:pointer;transition:all .12s;white-space:nowrap;-webkit-tap-highlight-color:transparent}
     .btn:active{background:var(--bdr)}.btn-p{background:var(--acc);color:#fff;border-color:var(--acc)}.btn-p:active{opacity:.85}
     .btn-ok{background:var(--ok);color:#fff;border-color:var(--ok)}.btn-er{background:var(--err);color:#fff;border-color:var(--err)}
     .btn-sm{padding:6px 10px;font-size:12px}
     .btn-icon{width:40px;height:40px;padding:0;display:flex;align-items:center;justify-content:center;font-size:18px;border-radius:10px}

     /* ===== SIDEBAR DRAWER ===== */
     .drawer-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:90}
     .drawer-overlay.on{display:block}
     .drawer{position:fixed;top:0;bottom:0;left:-280px;width:280px;background:var(--bg1);border-right:1px solid var(--bdr);z-index:95;display:flex;flex-direction:column;transition:left .25s ease;padding-top:env(safe-area-inset-top)}
     .drawer.on{left:0}
     .drawer-header{display:flex;align-items:center;justify-content:space-between;padding:14px 12px;border-bottom:1px solid var(--bdr)}
     .drawer-header .title{font-size:14px;font-weight:700}
     .drawer-close{width:32px;height:32px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg3);color:var(--t2);font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center}
     .drawer-body{flex:1;overflow-y:auto;padding:8px;-webkit-overflow-scrolling:touch}
     .sb-lbl{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:var(--t3);margin:12px 0 6px;padding:0 8px}
     .sb-i{display:flex;align-items:center;gap:10px;padding:10px 10px;border-radius:8px;cursor:pointer;font-size:13px;color:var(--t2);transition:all .1s;border:1px solid transparent;-webkit-tap-highlight-color:transparent}
     .sb-i:active{background:var(--bg3);color:var(--t1)}.sb-i.on{background:var(--bg3);color:var(--acc);border-color:var(--bdr)}
     .sb-ico{width:24px;height:24px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;flex-shrink:0}
     .drawer-actions{padding:10px;border-top:1px solid var(--bdr);display:flex;gap:8px;padding-bottom:max(10px,env(safe-area-inset-bottom))}
     .drawer-actions .btn{flex:1;text-align:center;padding:10px;font-size:13px}

     /* ===== MAIN CONTENT ===== */
     .main{flex:1;display:flex;flex-direction:column;overflow:hidden}
     .content{flex:1;display:flex;flex-direction:column;overflow:hidden;-webkit-overflow-scrolling:touch}
     .page{display:none;flex:1;overflow-y:auto;padding:14px;-webkit-overflow-scrolling:touch}.page.on{display:flex;flex-direction:column}

     /* ===== BOTTOM NAV ===== */
     .bottom-nav{height:60px;background:var(--bg2);border-top:1px solid var(--bdr);display:flex;flex-shrink:0;padding-bottom:env(safe-area-inset-bottom)}
     .nav-btn{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:none;border:none;color:var(--t3);font-size:10px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:all .1s}
     .nav-btn:active{background:var(--bg4)}
     .nav-btn.on{color:var(--acc)}
     .nav-ico{font-size:22px;line-height:1}
     .nav-label{font-size:10px;font-weight:500}

     /* ===== DASHBOARD ===== */
     .ph h1{font-size:22px;font-weight:700;margin-bottom:4px}.ph p{font-size:13px;color:var(--t2);margin-bottom:16px}
     .stats{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:16px}
     .st{background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;padding:14px;text-align:center}
     .st-v{font-size:28px;font-weight:800}.st-l{font-size:11px;color:var(--t2);margin-top:2px}
     .grid{display:grid;grid-template-columns:1fr;gap:10px}
     /* ===== RUNNER CARD ===== */
     #runner-card{margin-top:12px}
     .runner-box{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px}
     .runner-h{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:800;margin-bottom:8px}
     .runner-dot{width:8px;height:8px;border-radius:50%;background:var(--t3)}
     .runner-dot.on{background:var(--ok);box-shadow:0 0 8px rgba(63,185,80,.6)}
     .runner-line{font-size:11.5px;color:var(--t2);margin-bottom:10px;word-break:break-all}
     .runner-line b{color:var(--t1)}
     .runner-btns{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}
     /* Эстафета: два лимита + отсчёт вводим прямо в карточке раннера. */
     .runner-lbl{display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t3)}
     .runner-inp{width:58px;padding:6px 8px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:13px;font-family:monospace;outline:none}
     .runner-inp:focus{border-color:var(--acc)}
     .runner-list{display:flex;flex-direction:column;gap:6px;margin-bottom:8px}
     .runner-item{display:flex;align-items:center;gap:8px;background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:8px}
     .runner-item select{flex:0 0 118px;padding:6px;font-size:11.5px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);outline:none}
     .runner-name{flex:1;min-width:0;font-size:12px;word-break:break-word}
     .runner-meta{display:block;font-size:10px;color:var(--t3);margin-top:2px}
     .runner-res{font-size:12px;color:var(--ok);background:rgba(63,185,80,.08);border:1px solid rgba(63,185,80,.3);border-radius:8px;padding:8px;margin-bottom:8px}
     .runner-res a{color:var(--acc)}
     .runner-err{font-size:12px;color:var(--err);background:rgba(248,81,73,.08);border:1px solid rgba(248,81,73,.3);border-radius:8px;padding:8px;margin-bottom:8px}
     .runner-busy{font-size:12px;color:var(--warn);margin-bottom:8px}
     .card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:16px}
     .card-h{display:flex;align-items:center;gap:12px;margin-bottom:10px}
     .card-ico{width:40px;height:40px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800}
     .card-n{font-size:15px;font-weight:600}.card-v{font-size:10px;color:var(--t3);font-family:monospace}
     .tag{font-size:10px;padding:3px 8px;border-radius:8px;display:inline-block;margin-right:4px}
     .tag-on{color:var(--ok);background:rgba(63,185,80,.12)}.tag-off{color:var(--err);background:rgba(248,81,73,.12)}
     .mini-badge{font-size:8px;font-weight:700;padding:2px 6px;border-radius:4px;border:1px solid;margin-left:4px;vertical-align:2px}
     .card-badges{height:16px;display:flex;gap:4px;overflow:hidden}
     .test-res{font-size:10px;color:var(--t3);min-height:14px;padding:5px 0 0;font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
     .card-foot{display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:10px;border-top:1px solid var(--bdr)}
     .card-dir{flex:1;font-size:14px;color:var(--t2);font-family:monospace;padding:8px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;outline:none;color:var(--t1);width:100%}
     .card-dir:focus{border-color:var(--acc)}
     .apply-menu{display:none;position:fixed;bottom:70px;left:10px;right:10px;background:var(--bg2);border:1px solid var(--bdr);border-radius:12px;min-width:200px;z-index:50;box-shadow:0 -4px 24px rgba(0,0,0,.5);max-height:60vh;overflow-y:auto}
     .apply-menu.on{display:block}
     .apply-menu-title{padding:12px 14px;font-size:13px;font-weight:600;border-bottom:1px solid var(--bdr);color:var(--t2)}
     .apply-item{display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;font-size:14px;color:var(--t2);border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .apply-item:last-child{border-bottom:none}
     .apply-item:active{background:var(--bg3);color:var(--t1)}

     /* ===== TERMINAL ===== */
     .term-page{display:none;flex:1;flex-direction:column;overflow:hidden}.term-page.on{display:flex}
     .term-topbar{display:flex;align-items:center;background:var(--bg1);border-bottom:1px solid var(--bdr);flex-shrink:0}
     .tabs-row{display:flex;overflow-x:auto;flex:1;-webkit-overflow-scrolling:touch;touch-action:pan-x pan-y;overscroll-behavior:contain}
     .tab{display:flex;align-items:center;gap:6px;padding:10px 14px;font-size:13px;color:var(--t2);cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap;flex-shrink:0;-webkit-tap-highlight-color:transparent}
     .tab:active{background:var(--bg3)}.tab.on{color:var(--acc);border-bottom-color:var(--acc);background:var(--bg2)}
     .tab-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
     .tab-x{margin-left:4px;opacity:.4;font-size:15px}.tab-x:active{opacity:1;color:var(--err)}
     .tab-add{padding:10px 12px;color:var(--t3);cursor:pointer;font-size:18px;flex-shrink:0}.tab-add:active{color:var(--acc)}
     .term-controls{display:flex;align-items:center;gap:6px;padding:0 10px;border-left:1px solid var(--bdr);flex:0 1 auto;min-width:0;overflow-x:auto;-webkit-overflow-scrolling:touch;touch-action:pan-x;overscroll-behavior:contain;scrollbar-width:none}
     .term-controls::-webkit-scrollbar{display:none}
     .term-controls>*{flex-shrink:0}
     .tc-btn{width:36px;height:36px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg3);color:var(--t2);font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;-webkit-tap-highlight-color:transparent}
     .tc-btn:active{background:var(--bdr);color:var(--t1)}.tc-btn,.arr-btn{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
     .tc-btn:focus{outline:none;-webkit-tap-highlight-color:transparent}
     .zoom-label{font-size:12px;color:var(--t3);min-width:44px;text-align:center;font-family:monospace}
     .term-container{flex:1;display:flex;overflow:hidden;background:#000;flex-direction:column;flex-wrap:nowrap;position:relative}
     .term-arrows{position:absolute;bottom:8px;right:8px;z-index:2;display:flex;flex-direction:column;align-items:center;gap:4px;opacity:.7;transition:opacity .2s}
     .term-arrows:active{opacity:1}
     .arr-row{display:flex;gap:4px}
     .arr-btn{width:42px;height:42px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);color:#e6edf3;font-size:16px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
     .arr-btn:active{background:rgba(255,255,255,.25)}
     .arr-center{font-size:10px;width:52px}
     .arr-extra{display:flex;gap:4px;margin-top:2px}
     .arr-wide{width:auto;padding:0 14px;font-size:11px}
     .term-panel{display:none;flex:1;width:100%;flex-direction:column;overflow:hidden;border:1px solid var(--bdr);min-height:200px;position:relative}
     .term-panel.on{display:flex}
     .term-header{display:flex;align-items:center;justify-content:space-between;padding:6px 12px;background:var(--bg2);border-bottom:1px solid var(--bdr);flex-shrink:0}
     .term-header-title{font-size:11px;color:var(--t2);display:flex;align-items:center;gap:6px}
     .term-info{font-size:10px;color:var(--t3);font-family:monospace}
     .term{flex:1;background:#000;padding:2px;overflow:hidden}
     .term .xterm{height:100%}
     .term .xterm-viewport{overflow-y:auto!important;overflow-x:hidden!important;-webkit-overflow-scrolling:touch!important}.term .xterm-viewport{touch-action:pan-x pan-y!important}
     .term .xterm-viewport::-webkit-scrollbar{width:6px}
     .term .xterm-viewport::-webkit-scrollbar-track{background:transparent}
     .term .xterm-viewport::-webkit-scrollbar-thumb{background:var(--bdr);border-radius:3px}
     .term-wrap{flex:1;display:flex;flex-direction:row;overflow:hidden;min-width:0;position:relative}
     .term-wrap .term{flex:1;min-width:0}
     /* Виртуальная мышь терминала — та же, что на вкладке «Экран»: тянуть по
        подушечке = колесо мыши, ▲▼ = шаг, ⠿ тащит сам блок. По умолчанию
        плавает СВЕРХУ слева (свежий вывод терминала не перекрывается), в покое
        полупрозрачная; тап по ручке возвращает блок наверх. */
     .term-scroll{position:absolute;right:8px;top:8px;left:auto;z-index:4;display:flex;flex-direction:row;align-items:stretch;border-radius:10px;background:rgba(13,17,23,.72);border:1px solid rgba(240,246,252,.18);box-shadow:0 2px 8px rgba(0,0,0,.4);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);overflow:hidden;touch-action:none;opacity:.5;transition:opacity .15s ease,box-shadow .15s ease}
     .term-scroll.chasing{opacity:1;box-shadow:0 2px 12px rgba(0,0,0,.6),0 0 0 1px rgba(88,166,255,.35)}
     .term-mouse-pad{width:62px;height:58px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;font-size:22px;line-height:1;color:rgba(230,237,243,.85);background:radial-gradient(circle at center,rgba(88,166,255,.18),rgba(255,255,255,.04) 62%,transparent 72%);border-right:1px solid rgba(240,246,252,.14);touch-action:none;cursor:grab;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
     .term-mouse-pad:active{cursor:grabbing;background-color:rgba(88,166,255,.14)}
     .term-mouse-wheel{display:flex;flex-direction:column;flex:0 0 auto}
     .term-scroll-arr{width:40px;height:29px;flex-shrink:0;border:none;background:transparent;color:#e6edf3;font-size:14px;line-height:1;cursor:pointer;touch-action:none;padding:0;flex:0 0 auto}
     .term-scroll-arr:active,.term-scroll-arr.on{background:var(--acc);color:#0d1117}
     .term-scroll-arr.dim{opacity:.35}
     .term-scroll-handle{width:17px;flex-shrink:0;border:none;background:rgba(255,255,255,.06);color:rgba(230,237,243,.8);font-size:12px;line-height:1;cursor:grab;touch-action:none;padding:0;align-self:stretch}
     .term-scroll-handle:active{cursor:grabbing}
     .term-scroll-track{display:none}
     .term-cd{display:none;position:absolute;left:12px;right:auto;bottom:12px;background:rgba(210,153,34,.14);border:1px solid var(--warn);color:var(--warn);border-radius:9px;font-size:12px;font-weight:700;font-family:monospace;padding:4px 10px;z-index:3;pointer-events:none;white-space:nowrap}
     .term-cd.on{display:block}

     /* ===== FILE MANAGER ===== */
     .fm-header{display:flex;gap:6px;padding:8px 0;margin-bottom:8px;flex-shrink:0;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;-ms-overflow-style:none;touch-action:pan-x pan-y;overscroll-behavior:contain}.fm-header::-webkit-scrollbar{display:none}
     .fm-header .btn{padding:8px 12px;font-size:13px}
     .fm-path-row{display:flex;gap:6px;margin-bottom:8px;flex-shrink:0}
     .fm-path-row input{flex:1;padding:8px 12px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;outline:none}
     .fm-path-row input:focus{border-color:var(--acc)}
     .fm-sidebar{max-height:140px;overflow-y:auto;background:var(--bg1);border:1px solid var(--bdr);border-radius:10px;margin-bottom:10px}
     .fm-sidebar-title{padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--t3);border-bottom:1px solid var(--bdr)}
     .fm-sidebar-item{display:flex;align-items:center;gap:8px;padding:8px 10px;font-size:13px;color:var(--t2);cursor:pointer;border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .fm-sidebar-item:active{background:var(--bg3)}
     .fm-list{flex:1;overflow-y:auto;border:1px solid var(--bdr);border-radius:10px;background:var(--bg0);-webkit-overflow-scrolling:touch}
     .fm-item{display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .fm-item:active{background:var(--bg3)}.fm-item.fm-sel{background:rgba(88,166,255,.1)}
     .fm-ico{font-size:24px;flex-shrink:0;width:48px;text-align:center}
     .fm-name{flex:2;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
     .fm-size{font-size:11px;color:var(--t3);flex-shrink:0;min-width:60px;text-align:right}
     .fm-info{padding:6px 0;font-size:11px;color:var(--t3)}

     /* ===== MODELS FULL ===== */
     .models-full-actions{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}
     .models-full-actions .btn{font-size:13px;padding:8px 12px}
     #models-full-info{font-size:12px;color:var(--t3);display:flex;align-items:center}
     .tool-config-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px;margin-bottom:10px}
     .tool-config-card .tc-name{font-size:14px;font-weight:600;margin-bottom:6px}
     .tool-config-card .tc-key{font-size:10px;color:var(--t3);font-family:monospace;word-break:break-all;margin-top:4px}
     .model-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px;margin-bottom:10px}
     .model-card:active{border-color:var(--acc)}
     .model-card.selected{border-color:var(--ok);background:rgba(63,185,80,.05)}
     .model-card .model-name{font-size:14px;font-weight:600;margin-bottom:4px}
     .model-card .model-id{font-size:10px;color:var(--t3);font-family:monospace;word-break:break-all}

     /* ===== MODAL ===== */
     .modal-bg{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:100;align-items:flex-end;justify-content:center;cursor:pointer}
     .modal-bg.on{display:flex}
     .modal{background:var(--bg2);border:1px solid var(--bdr);border-radius:16px 16px 0 0;padding:20px;width:100%;max-height:85dvh;display:flex;flex-direction:column}
     .modal h2{font-size:18px;font-weight:600;margin-bottom:14px}
     .modal-bar{display:flex;gap:8px;margin-bottom:12px}
     .modal-bar input{flex:1;padding:10px 12px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;outline:none}
     .modal-bar input:focus{border-color:var(--acc)}
     .modal-drives{display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap}
     .drive-btn{padding:8px 12px;background:var(--bg3);border:1px solid var(--bdr);border-radius:8px;color:var(--t2);font-size:13px;cursor:pointer;-webkit-tap-highlight-color:transparent}
     .drive-btn:active{border-color:var(--acc);color:var(--t1)}
     .git-pre{background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;padding:12px;overflow:auto;max-height:50vh;font-size:12px;line-height:1.6;white-space:pre-wrap;word-break:break-all;-webkit-overflow-scrolling:touch}
     .git-file{display:flex;gap:8px;align-items:baseline;padding:4px 0;font-size:13px;font-family:monospace}
     .git-code{color:var(--warn);width:20px;flex-shrink:0}
     .modal-list{flex:1;overflow-y:auto;max-height:300px;border:1px solid var(--bdr);border-radius:8px;background:var(--bg0);-webkit-overflow-scrolling:touch}
     .modal-actions{display:flex;gap:8px;margin-top:14px;justify-content:flex-end}
     .modal-actions .btn{padding:10px 16px;font-size:14px}
     .newterm-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}
     .newterm-tool{display:flex;align-items:center;gap:10px;padding:12px;background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;cursor:pointer;-webkit-tap-highlight-color:transparent}
     .newterm-tool:active{border-color:var(--acc)}.newterm-tool.off{opacity:.35;pointer-events:none}
     .storage-type-btn{padding:8px 12px;background:var(--bg3);border:1px solid var(--bdr);border-radius:8px;color:var(--t2);font-size:13px;cursor:pointer;-webkit-tap-highlight-color:transparent}
     .storage-type-btn:active{border-color:var(--acc);color:var(--t1)}.storage-type-btn.on{border-color:var(--acc);color:var(--acc);background:rgba(88,166,255,.1)}

     /* ===== MISC ===== */
     .term-close{margin-left:auto;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--t3);cursor:pointer;flex-shrink:0;transition:all .1s}.term-close:hover,.term-close:active{color:var(--err);background:rgba(248,81,73,.15)}
     ::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--bdr);border-radius:3px}::-webkit-scrollbar-thumb:hover{background:var(--t3)}
     input,select,textarea{font-size:16px!important}
     .model-menu{position:fixed;bottom:70px;left:10px;right:10px;background:var(--bg2);border:1px solid var(--bdr);border-radius:12px;z-index:50;box-shadow:0 -4px 24px rgba(0,0,0,.5);max-height:60vh;overflow-y:auto}
     .model-menu-title{padding:12px 14px;font-size:13px;font-weight:600;border-bottom:1px solid var(--bdr);color:var(--t2);display:flex;justify-content:space-between;align-items:center}
     .model-menu-title input{flex:1;margin-left:10px;padding:6px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:14px;outline:none}
     .model-menu-list{max-height:300px;overflow-y:auto}
     .model-menu-foot{padding:10px 14px;border-top:1px solid var(--bdr)}
     .model-menu-foot .btn{width:100%;text-align:center;font-size:13px}
   </style>
 </head>
 <body>

   <!-- TOPBAR -->
   <div class="topbar">
     <button class="btn btn-icon" onclick="toggleDrawer()" style="padding:0;width:36px;height:36px;font-size:18px">☰</button>
     <div class="logo">◆ NPM Hub <span id="hub-ver" class="hub-ver"></span></div>
     <div class="topbar-right">
       <button class="btn btn-sm" onclick="hubUpdate()" id="hub-update-btn" style="font-size:12px;padding:6px 8px" title="Проверить обновления на GitHub">🔄</button>
       <span id="sess-clock" class="sess-clock" title="Сессия раннера: сколько уже прошло из лимита (джоба убивается на 6-м часу без предупреждения)">…</span>
       <div style="position:relative">
         <button class="btn btn-sm" onclick="toggleModelMenu(event)" id="model-btn" style="font-size:12px;padding:6px 10px">
           <span id="model-name">OWL Alpha</span> ▾
         </button>
       </div>
       <span class="access-badge" id="access-mode"></span>
       <a id="web-login-link" class="tunnel-url" style="display:none" target="_blank" rel="noopener">Войти через веб</a>
       <a id="tunnel-link" class="tunnel-badge" style="display:none" target="_blank" rel="noopener">🌐</a>
       <span id="tunnel-url" class="tunnel-url" style="display:none" onclick="copyTunnelUrl()"></span>
     </div>
   </div>

   <!-- DRAWER (sidebar replacement) -->
   <div class="drawer-overlay" id="drawer-overlay" onclick="toggleDrawer()"></div>
   <div class="drawer" id="drawer">
     <div class="drawer-header">
       <div class="title">Панель</div>
       <button class="drawer-close" onclick="toggleDrawer()">✕</button>
     </div>
     <div class="drawer-body">
       <div class="sb-lbl">Инструменты</div>
       <div id="tool-list"></div>
       <div class="sb-lbl" style="margin-top:14px">Сессии</div>
       <div id="term-list"></div>
     </div>
     <div class="drawer-actions">
       <button class="btn" onclick="openTerminal();toggleDrawer()">>_ Терминал</button>
+      <button class="btn" onclick="location.href='/apps';toggleDrawer()" title="Приложения этого телефона — список и запуск с устройства">📲</button>
       <button class="btn btn-p" onclick="showNewTermModal();toggleDrawer()">+ Сессия</button>
     </div>
   </div>

   <!-- MAIN -->
   <div class="main">
     <div class="content">

       <!-- DASHBOARD -->
       <div class="page" id="p-dashboard">
         <div class="ph"><h1>Dashboard</h1><p>AI инструменты — выберите папку и нажмите Применить</p></div>

         <!-- Сайт хаба: показывается при каждом открытии хаба — копировать адрес
              или открыть панель в системном браузере устройства. -->
         <div id="site-card" class="card" style="margin-bottom:12px">
           <div class="card-h">
             <div class="card-ico" style="background:rgba(188,140,255,.12);color:var(--pur)">🌐</div>
             <div><div class="card-n">Сайт хаба</div><div class="card-v">Панель NPM Hub</div></div>
             <span class="tag tag-on" id="site-card-state" style="margin-left:auto">…</span>
           </div>
           <div class="runner-line" id="site-card-url" style="font-family:monospace">…</div>
           <div class="runner-btns">
             <button class="btn btn-p" onclick="openHubExternal(hubSiteUrl())" title="Открыть панель в системном браузере устройства — он переживает перезапуск приложения">🌐 Перейти</button>
             <button class="btn" onclick="copyHubSiteUrl()" title="Скопировать адрес сайта">📋 Скопировать</button>
           </div>
         </div>

         <div class="stats" id="stats"></div>
         <div class="grid" id="grid"></div>
         <div id="runner-card"></div>
       </div>

       <!-- TERMINAL -->
       <div class="term-page" id="p-terminal">
         <div class="term-topbar">
           <div class="tabs-row" id="tabs"></div>
           <div class="term-controls">
             <button class="tc-btn" onclick="killTerm()" ontouchend="event.preventDefault();killTerm()" oncontextmenu="event.preventDefault()" title="Стоп">⏹</button>
             <button class="tc-btn" onclick="sendEscape()" ontouchend="event.preventDefault();sendEscape()" oncontextmenu="event.preventDefault()" title="Escape">Esc</button>
             <button class="tc-btn" onclick="pasteClipboard()" ontouchend="event.preventDefault();pasteClipboard()" oncontextmenu="event.preventDefault()" title="Вставить">📋</button>
             <button class="tc-btn" onclick="copySelection()" ontouchend="event.preventDefault();copySelection()" oncontextmenu="event.preventDefault()" title="Копировать">⧉</button>
             <button class="tc-btn" onclick="restartTerm()" ontouchend="event.preventDefault();restartTerm()" oncontextmenu="event.preventDefault()" title="Перезапустить">⟲</button>
             <button class="tc-btn" onclick="zoomTerm(-1)" ontouchend="event.preventDefault();zoomTerm(-1)" oncontextmenu="event.preventDefault()">−</button>
             <span class="zoom-label" id="zoom-label">60%</span>
             <button class="tc-btn" onclick="zoomTerm(1)" ontouchend="event.preventDefault();zoomTerm(1)" oncontextmenu="event.preventDefault()">+</button>
             <button class="tc-btn" onclick="zoomTerm(0)" ontouchend="event.preventDefault();zoomTerm(0)" oncontextmenu="event.preventDefault()">⟲</button>
             <button class="tc-btn" onclick="toggleFullscreen()" ontouchend="event.preventDefault();toggleFullscreen()" oncontextmenu="event.preventDefault()">⛶</button>
           </div>
         </div>
         <div class="term-container" id="term-container">
           <div class="term-arrows" id="term-arrows">
             <button class="arr-btn" onclick="sendKey('\x1b[A')" ontouchend="event.preventDefault();sendKey('\x1b[A')" oncontextmenu="event.preventDefault()">▲</button>
             <div class="arr-row">
               <button class="arr-btn" onclick="sendKey('\x1b[D')" ontouchend="event.preventDefault();sendKey('\x1b[D')" oncontextmenu="event.preventDefault()">◀</button>
               <button class="arr-btn arr-center" onclick="sendKey('\t')" ontouchend="event.preventDefault();sendKey('\t')" oncontextmenu="event.preventDefault()">Tab</button>
               <button class="arr-btn" onclick="sendKey('\x1b[C')" ontouchend="event.preventDefault();sendKey('\x1b[C')" oncontextmenu="event.preventDefault()">▶</button>
             </div>
             <button class="arr-btn" onclick="sendKey('\x1b[B')" ontouchend="event.preventDefault();sendKey('\x1b[B')" oncontextmenu="event.preventDefault()">▼</button>
             <div class="arr-extra">
               <button class="arr-btn arr-wide" onclick="sendKey('\r')" ontouchend="event.preventDefault();sendKey('\r')" oncontextmenu="event.preventDefault()">Enter</button>
               <button class="arr-btn arr-wide" onclick="sendKey('/')" ontouchend="event.preventDefault();sendKey('/')" oncontextmenu="event.preventDefault()">/</button>
             </div>
           </div>
         </div>
       </div>

       <!-- FILES -->
       <div class="page on" id="p-files">
         <div class="fm-sidebar">
           <div class="fm-sidebar-title">Устройства</div>
           <div id="devices-list"></div>
           <div class="fm-sidebar-title" style="border-top:1px solid var(--bdr)">Хранилища</div>
           <div id="storages-list"></div>
           <div style="padding:8px;border-top:1px solid var(--bdr)">
             <button class="btn" onclick="showAddStorageModal()" style="width:100%;text-align:center;font-size:13px">+ Добавить</button>
           </div>
         </div>
         <div class="fm-path-row">
           <input type="text" id="fm-path" onkeydown="if(event.key==='Enter')fmBrowse(this.value)">
           <button class="btn" onclick="fmBrowse(document.getElementById('fm-path').value)">Go</button>
         </div>
         <div class="fm-header">
           <button class="btn" onclick="fmGoUp()">↑</button>
           <button class="btn" onclick="fmGoHome()">🏠</button>
           <button class="btn" onclick="fmRefresh()">⟳</button>
           <button class="btn" onclick="toggleFileSel(true)">Выделить все</button>
           <button class="btn" onclick="fmMkdir()">📁+</button>
           <button class="btn" onclick="fmCreateFile()">📄+</button>
           <button class="btn" onclick="fmRename()">✏️</button>
           <button class="btn" onclick="fmDelete()">🗑️</button>
           <button class="btn" onclick="fmDownloadMulti()" title="Скачать на телефон — файл попадёт в папку Загрузки (Download), вне Android/data">📥 Multi-download</button>
           <button class="btn" onclick="fmDownloadSingle()" title="Скачать на телефон — файл попадёт в папку Загрузки (Download), вне Android/data">⬇ Single</button>
           <button class="btn" onclick="fmOpenView()" title="Открыть во встроенном просмотрщике: текст — редактор с сохранением, фото/видео/PDF — просмотр (работает и из кеша)">👁</button>
           <button class="btn" onclick="fmCacheSelection()" title="Сохранить файл/папку в кеш на устройстве (IndexedDB) — переживает отключение раннера, как у PWA">💾 В кеш</button>
           <button class="btn" onclick="fmArchive()" title="Скачать как tar.xz (распаковывается любым архиватором)">📦</button>
           <button class="btn" onclick="fmSaveGithub()" title="Сохранить в GitHub">⬆️GH</button>
           <button class="btn" onclick="fmUpload()" title="Файлы (все виды, картинки — тоже, множественный выбор через SAF)">⬆</button>
           <button class="btn" onclick="fmUploadFolder()" title="Папку целиком — в браузере, не в APK">⬆📁</button>
           <button class="btn" onclick="gitFmShow()" title="Ручной git: создать репо / коммит / push этой папки">📝 git</button>
           <button class="btn" onclick="fmOpenScreen()" title="Открыть на экране (вкладка Экран)">🖥</button>
           <div style="position:relative;margin-left:auto">
             <button class="btn btn-p" onclick="toggleFmMenu(event)">▶</button>
             <div class="apply-menu" id="fm-apply-menu"></div>
           </div>
         </div>
         <div class="fm-list" id="fm-list"></div>
         <div class="fm-info" id="fm-info"></div>
         <div class="fm-transfer" id="fm-transfer" style="margin-top:8px;display:none;background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:8px;font-size:11px;color:var(--t3)">
           <div id="fm-transfer-name"></div>
           <div style="margin-top:4px;height:6px;border-radius:3px;background:var(--bdr);overflow:hidden"><div id="fm-transfer-bar" style="height:100%;width:0%;background:#58a6ff"></div></div>
           <div style="margin-top:4px"><span id="fm-transfer-progress"></span> · <span id="fm-transfer-speed"></span>/s · осталось <span id="fm-transfer-time"></span></div>
           <div style="margin-top:4px"><span id="fm-transfer-transferred"></span><span id="fm-transfer-total"></span></div>
         </div>
       </div>

 <!-- LINUX DESKTOP (VNC) — ОДИН ЭКРАН ДЛЯ ВСЕГО (RDP/VNC) -->
       <div class="page" id="p-linux" style="padding:0;flex-direction:column;height:100%">
         <!-- Одна тонкая строка: только управление экраном. Адрес, звук, починка —
              во вкладке «Настройки» (p-screen-settings). Экран — экран, не панель. -->
         <div class="linux-bar">
           <span id="linux-status" class="tag">…</span>
           <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨</button>
           <button class="btn btn-sm" id="linux-zoom-btn" onclick="linuxZoomToggle()" title="Заполнить / весь стол / 1:1">🔎</button>
           <button class="btn btn-sm" id="linux-perf-btn" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡</button>
           <button class="btn btn-sm" id="linux-mouse-btn" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱</button>
           <button class="btn btn-sm" onclick="linuxFullscreen()" title="На весь экран + поворот в ландшафт">⛶</button>
           <span id="linux-note"></span>
         </div>
         <style>
           /* ⛶ — экран на весь экран без потери noVNC-сессии.
              100dvh: на мобильных адресная строка Safari/Chrome иначе «съедает»
              часть высоты и картинка не заполняет экран. */
           #p-linux.linux-full{position:fixed!important;inset:0!important;height:100vh!important;height:100dvh!important;z-index:99999;background:#000}
           #p-linux.linux-full > .linux-bar, #p-linux.linux-full > #linux-more{display:none!important}
           /* «Просто рабочий стол»: на странице «Экран» не нужна шапка приложения —
              уйти можно нижним меню, а в полном экране есть ✕. */
           body.pg-linux .topbar{display:none}
           .linux-bar{display:flex;gap:6px;padding:6px 8px;background:var(--bg1);border-bottom:1px solid var(--bdr);flex-shrink:0;align-items:center;flex-wrap:nowrap;overflow:hidden}
           .linux-bar #linux-note{font-size:10px;color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
           #linux-more{display:flex;gap:6px;padding:6px 8px;background:var(--bg2);border-bottom:1px solid var(--bdr);flex-shrink:0;flex-wrap:wrap;align-items:center}
           #linux-more[hidden]{display:none}
           #linux-read{display:flex;gap:6px;align-items:center;flex-wrap:wrap;width:100%}
           #p-linux.linux-full #linux-stack{flex:1 1 auto;height:100%}
           /* В полном экране тулбары скрыты, поэтому клавиатура, масштаб и
              выход живут здесь — иначе за клавиатурой приходилось выходить из
              полноэкранного режима (на это и жаловались). */
           .linux-fsctl{display:none}
           #p-linux.linux-full .linux-fsctl{display:flex;gap:8px;position:absolute;top:10px;right:10px;z-index:100000}
           #p-linux.linux-full .linux-fsctl button{
             background:rgba(13,17,23,.8);color:#e6edf3;border:1px solid rgba(240,246,252,.25);
             border-radius:50%;width:40px;height:40px;font-size:16px;line-height:1}
           @media (max-width:560px){ .linux-hint{display:none!important} }
           /* ── Виртуальная мышь ──────────────────────────────────────────────
              Палец по картинке — плохой курсор: он закрывает то место, куда
              целишься, промах по мелкой кнопке уходит в пустоту, а скролл
              вообще некуда деть. Поэтому мышь отдельная: слева сенсор, справа
              ЛКМ/ПКМ, в центре колесо стрелками. */
           #linux-mouse{position:absolute;left:0;right:0;bottom:0;z-index:99990;display:flex;gap:8px;align-items:stretch;
             padding:8px;background:linear-gradient(180deg,rgba(13,17,23,.78),rgba(13,17,23,.95));
             border-top:1px solid rgba(240,246,252,.18);backdrop-filter:blur(6px);
             touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
           #linux-mouse[hidden]{display:none}
           .lm-pad{flex:1 1 auto;min-width:96px;min-height:104px;border-radius:12px;border:1px dashed rgba(240,246,252,.28);
             background:rgba(255,255,255,.05);display:flex;align-items:center;justify-content:center;color:var(--t3);
             font-size:10px;line-height:1.35;text-align:center;touch-action:none;position:relative;overflow:hidden}
           .lm-pad.active{background:rgba(88,166,255,.16);border-color:var(--acc)}
           .lm-pad-hint{pointer-events:none;padding:0 8px}
           .lm-buttons{display:flex;flex-direction:column;gap:6px;width:74px;flex:0 0 auto}
           .lm-btn{flex:1;border-radius:10px;border:1px solid rgba(240,246,252,.22);background:rgba(255,255,255,.07);
             color:#e6edf3;font-size:12px;font-weight:700;touch-action:none}
           .lm-btn.on,.lm-btn:active{background:var(--acc);color:#0d1117;border-color:var(--acc)}
           .lm-wheel{display:flex;flex-direction:column;gap:4px;width:88px;align-items:center;justify-content:center;flex:0 0 auto}
           .lm-wheel-mid{display:flex;gap:4px}
           .lm-arr{width:40px;height:30px;border-radius:8px;border:1px solid rgba(240,246,252,.22);
             background:rgba(255,255,255,.07);color:#e6edf3;font-size:13px;line-height:1;touch-action:none}
           .lm-arr.on,.lm-arr:active{background:var(--acc);color:#0d1117;border-color:var(--acc)}
           .lm-close{position:absolute;top:2px;right:4px;width:24px;height:24px;border-radius:50%;
             border:1px solid rgba(240,246,252,.25);background:rgba(13,17,23,.75);color:#e6edf3;font-size:11px;line-height:1;padding:0}
           #p-linux.linux-full #linux-mouse{padding-bottom:max(8px,env(safe-area-inset-bottom))}
         </style>
         <div id="browser-agent-hint" style="display:none;padding:8px 10px;background:rgba(88,166,255,.14);border-bottom:1px solid var(--bdr);font-size:12px;color:var(--acc);align-items:center;gap:8px;flex-wrap:wrap;flex-shrink:0">
           <span>🔗 Агент прислал ссылку:</span><a id="browser-agent-url" href="#" target="_blank" style="color:var(--acc);word-break:break-all"></a>
           <button class="btn btn-p btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-agent-url').textContent)">🖥 Открыть на экране</button>
           <button class="btn btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-agent-url').textContent, true)">📱 вертикально</button>
           <span style="margin-left:auto;cursor:pointer" onclick="document.getElementById('browser-agent-hint').style.display='none'">✕</span>
         </div>
         <div id="linux-stack" style="flex:1;position:relative;background:#000">
           <div class="linux-fsctl">
             <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨</button>
             <button class="btn btn-sm" onclick="linuxZoomToggle()" title="Заполнить / 1:1">🔍</button>
             <button class="btn btn-sm" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡</button>
             <button class="btn btn-sm" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱</button>
             <button class="btn btn-sm" onclick="linuxFullscreen()" title="Выйти из полного экрана">✕</button>
           </div>
           <iframe id="linux-frame" style="width:100%;height:100%;border:none;display:none" allow="fullscreen; clipboard-read; clipboard-write" allowfullscreen></iframe>
           <!-- Виртуальная мышь: сенсор (палец двигает курсор), две кнопки и
                колесо стрелками. Работает поверх картинки экрана и не мешает
                прямым касаниям по ней. -->
           <div id="linux-mouse" hidden>
             <div class="lm-pad" id="lm-pad">
               <span class="lm-pad-hint">СЕНСОР · тяни — курсор, тап — клик, два тапа — двойной</span>
             </div>
             <div class="lm-buttons">
               <button class="lm-btn" id="lm-left" onpointerdown="vMouseDown(1)" onpointerup="vMouseUp(1)" onpointercancel="vMouseUp(1)" onpointerleave="vMouseUp(1)">ЛКМ</button>
               <button class="lm-btn" id="lm-right" onpointerdown="vMouseDown(4)" onpointerup="vMouseUp(4)" onpointercancel="vMouseUp(4)" onpointerleave="vMouseUp(4)">ПКМ</button>
             </div>
             <div class="lm-wheel">
               <button class="lm-arr" data-dir="up" onpointerdown="vMouseWheelStart('up')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▲</button>
               <div class="lm-wheel-mid">
                 <button class="lm-arr" data-dir="left" onpointerdown="vMouseWheelStart('left')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">◀</button>
                 <button class="lm-arr" data-dir="right" onpointerdown="vMouseWheelStart('right')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▶</button>
               </div>
               <button class="lm-arr" data-dir="down" onpointerdown="vMouseWheelStart('down')" onpointerup="vMouseWheelStop()" onpointercancel="vMouseWheelStop()" onpointerleave="vMouseWheelStop()">▼</button>
             </div>
             <button class="lm-close" onclick="linuxMouseToggle()" title="Скрыть мышь">✕</button>
           </div>
           <div id="linux-placeholder" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;color:var(--t3);text-align:center;padding:20px">
             <div style="font-size:48px;margin-bottom:16px">🖥</div>
             <div style="font-size:16px;font-weight:600;margin-bottom:8px;color:var(--t2)">Один экран</div>
             <div style="font-size:13px;max-width:320px;line-height:1.5">Всё — браузер, терминал, файлы — на одном рабочем столе Linux (openbox).<br>Вкладка <b>🎛 Настройки</b> откроет Chromium прямо здесь, звук уже 80%.<br><span style="color:var(--t3)">Телефон тоже здесь: «📱 вертикально» в настройках открывает вертикальный ютуб.</span></div>
             <button class="btn btn-p btn-sm" onclick="linuxRepair()" style="margin-top:14px">🔧 Починить экран</button>
             <div id="pulse-devices" style="margin-top:12px;font-size:11px;color:var(--t3);text-align:left"></div>
           </div>
         </div>
         <!-- cloud phone теперь не нужен отдельно — всё на одном DISPLAY -->
         <iframe id="cp-frame" style="display:none" allowfullscreen></iframe>
       </div>

       <!-- SCREEN SETTINGS — все настройки экрана в одном месте (раньше жили
            под «⋯» вкладки «Экран»). Экран — это экран, настройки — здесь. -->
       <div class="page" id="p-screen-settings">
         <div class="ph"><h1>🎛 Настройки экрана</h1><p>Вид, браузер, звук, AVD и голос на удалённом столе</p></div>

         <div id="screen-settings-body">
           <div class="card" style="margin-bottom:10px">
             <div class="card-h">
               <div class="card-ico" style="background:rgba(88,166,255,.12);color:var(--acc)">👁</div>
               <div><div class="card-n">Вид экрана</div><div class="card-v">Кнопки действуют на вкладке «Экран»</div></div>
             </div>
             <div style="display:flex;gap:6px;flex-wrap:wrap">
               <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨ Клавиатура</button>
               <button class="btn btn-sm" onclick="linuxZoomToggle()" title="Заполнить / весь стол / 1:1">🔎 Зум</button>
               <button class="btn btn-sm" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡ Плавность</button>
               <button class="btn btn-sm" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱 Мышь</button>
               <button class="btn btn-sm" onclick="linuxFullscreen()" title="На весь экран + поворот в ландшафт">⛶ Полный экран</button>
               <button class="btn btn-p btn-sm" onclick="showPage('linux')" title="Открыть экран">🖥 Открыть экран</button>
             </div>
           </div>

           <div id="linux-more">
             <input type="text" id="browser-url" placeholder="https://... — откроется на экране" value="https://www.youtube.com" style="flex:1;min-width:140px;padding:7px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:12px;outline:none" onkeydown="if(event.key==='Enter')linuxRunBrowser(this.value)">
             <button class="btn btn-p btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-url').value)" title="Открыть Chromium на экране (DISPLAY=:99)">Go · 🖥</button>
             <button class="btn btn-sm" onclick="linuxRunBrowser(document.getElementById('browser-url').value, true)" title="Вертикально (Shorts) — окно под экран телефона">📱 вертикально</button>
             <span id="pulse-status" class="tag" role="button" tabindex="0" onclick="event.stopPropagation();remoteAudioToggle()" onkeydown="if(event.key==='Enter'||event.key===' ')remoteAudioToggle()" title="Включить звук видео с удалённого экрана" style="font-size:10px;cursor:pointer">🔊</span>
             <input type="range" id="pulse-vol" min="0" max="100" value="80" style="width:80px" oninput="pulseSetVol(this.value)">
             <span id="pulse-vol-label" style="font-size:11px;font-family:monospace;min-width:36px;text-align:right">80%</span>
             <button class="btn btn-sm" onclick="pulseToggleMute()" title="Мьют">🔇</button>
             <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t2)" title="Сохраняется между перезапусками хаба"><span>AVD</span><input id="emulator-default" type="text" placeholder="pixel_7_api34" style="width:110px;padding:4px 6px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:11px" onkeydown="if(event.key==='Enter')saveEmulatorDefault()"></label>
             <button class="btn btn-sm" onclick="saveEmulatorDefault()" title="Сохранить AVD по умолчанию">✓ AVD</button>
             <button class="btn btn-sm" onclick="linuxRepair()" title="Пересобрать экран на этом раннере">🔧 починить</button>
             <!-- Читалка (TTS/OCR): жила во вкладке Chrome, а та дублировала
                  «Экран» (два браузера на одном телефоне) — переехала в настройки. -->
             <div id="linux-read">
               <span style="color:var(--pur);font-weight:700">🔊 TTS/OCR:</span>
               <button class="btn btn-p btn-sm" id="tts-play-btn" onclick="ttsToggle()">▶ Читать</button>
               <button class="btn btn-sm" onclick="ttsStop()">⏹ Стоп</button>
               <button class="btn btn-sm" onclick="ttsPause()">⏸ Пауза</button>
               <select id="tts-voice" style="padding:4px 6px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:11px;max-width:120px"></select>
               <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t2)"><input type="range" id="tts-rate" min="0.5" max="2" step="0.1" value="1" style="width:60px" oninput="ttsSetRate(this.value)"> <span id="tts-rate-label">1×</span></label>
               <label style="display:flex;align-items:center;gap:3px;font-size:11px;color:var(--t2)"><input type="checkbox" id="tts-autoscroll" checked> Авто-скролл</label>
               <label style="display:flex;align-items:center;gap:3px;font-size:11px;color:var(--t2)"><input type="checkbox" id="tts-bg" checked> В фоне</label>
               <button class="btn btn-sm" onclick="ocrCapture()" title="Распознать текст с экрана (OCR)">👁️ OCR</button>
               <span id="tts-status" style="font-size:10px;color:var(--t3);margin-left:auto">готов</span>
             </div>
           </div>
         </div>
         <style>
           #p-screen-settings #linux-more{display:flex;gap:6px;flex-wrap:wrap;align-items:center;background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:12px;margin-bottom:10px}
           #p-screen-settings #linux-more[hidden]{display:none}
           #p-screen-settings #linux-read{display:flex;gap:6px;align-items:center;flex-wrap:wrap;width:100%;border-top:1px solid var(--bdr);padding-top:10px;margin-top:4px}
           #p-screen-settings .btn:active{opacity:.85}
         </style>
       </div>

       <!-- SNAPSHOT — снапшоты рабочих репозиториев: выборочное восстановление -->
       <div class="page" id="p-snapshots">
         <div class="ph"><h1>📦 Снапшот</h1><p>Локальные репозитории из бэкапа. Вход в хаб больше не ждёт восстановление — выбираешь снапшот сам, когда вошёл.</p></div>
         <div id="snap-card" style="background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px;margin-bottom:10px">
           <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
             <span style="font-weight:700">Локальные репозитории</span>
             <span style="flex:1"></span>
             <button class="btn btn-sm" id="snap-reload" onclick="snapLoad(true)">🔄</button>
             <button class="btn btn-p btn-sm" id="snap-restore" onclick="snapRestore()" disabled>♻ Восстановить</button>
           </div>
           <div id="snap-note" style="font-size:12px;color:var(--t2);margin-top:8px">Снапшоты читаются по требованию (work-backup, только дерево — быстро).</div>
           <div id="snap-list" style="margin-top:10px"></div>
           <div id="snap-prog-wrap" style="display:none;margin-top:10px">
             <div style="display:flex;align-items:center;gap:8px">
               <div class="spin" id="snap-spin" style="width:16px;height:16px;border:2px solid var(--bdr);border-top-color:var(--acc);border-radius:50%;animation:snap-rot 1s linear infinite"></div>
               <span id="snap-prog-title" style="font-size:12px;font-weight:600;color:var(--acc)">Восстановление…</span>
               <span style="flex:1"></span>
               <span id="snap-prog-time" style="font-size:12px;color:var(--t3)">0:00</span>
             </div>
             <div id="snap-prog" style="margin-top:8px;max-height:220px;overflow-y:auto;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;padding:8px;font:11px/1.5 monospace;white-space:pre-wrap;word-break:break-word;color:var(--t2)"></div>
           </div>
         </div>
         <style>@keyframes snap-rot{to{transform:rotate(360deg)}} .snap-row{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--bdr);border-radius:10px;margin-bottom:8px;background:var(--bg0);cursor:pointer} .snap-row.sel{border-color:var(--acc);background:var(--bg3)} .snap-row input{position:absolute;opacity:0} </style>
       </div>

       <!-- GIT — local + GitHub repos + builds -->
       <div class="page" id="p-git">
         <div class="ph"><h1>🐙 Git</h1><p>Локальный репозиторий + GitHub: все репозитории, ветки, коммиты, сборки</p></div>
         <div style="display:flex;gap:8px;margin-bottom:12px;align-items:center;flex-wrap:wrap">
           <input type="text" id="git-path" placeholder="путь к локальному репозиторию (с .git)" style="min-width:180px;flex:1;padding:10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:13px;font-family:monospace;outline:none" onkeydown="if(event.key==='Enter')loadGit()">
           <button class="btn btn-p" onclick="loadGit()">⟳</button>
         </div>
         <div id="git-repo" style="font-size:11px;color:var(--t3);margin-bottom:8px"></div>
         <div id="git-status"></div>
         <div style="margin-top:16px;margin-bottom:6px;font-size:12px;color:var(--t2);font-weight:600">Diff</div>
         <pre class="git-pre" id="git-diff"></pre>
         <div style="margin-top:16px;margin-bottom:6px;font-size:12px;color:var(--t2);font-weight:600">Log</div>
         <pre class="git-pre" id="git-log"></pre>

         <!-- GitHub repos -->
         <div id="gh-repos-section" style="margin-top:24px;padding-top:16px;border-top:1px solid var(--bdr)">
           <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap">
             <h2 style="font-size:16px;font-weight:700">GitHub — Репозитории</h2>
             <button class="btn btn-p btn-sm" onclick="ghLoadRepos()">⟳ Обновить</button>
             <span id="gh-repos-count" style="font-size:11px;color:var(--t3)"></span>
           </div>
           <div id="gh-repos-grid" style="display:grid;grid-template-columns:1fr;gap:10px"></div>
         </div>

         <!-- Repo detail -->
         <div id="gh-repo-detail" style="display:none;margin-top:16px;padding-top:16px;border-top:1px solid var(--bdr)">
           <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">
             <button class="btn btn-sm" onclick="ghBackToList()">← Вернуться к списку</button>
             <h2 id="gh-repo-name" style="font-size:16px;font-weight:700"></h2>
             <span id="gh-repo-desc" style="font-size:12px;color:var(--t2)"></span>
             <div style="position:relative">
               <button class="btn btn-p btn-sm" onclick="toggleGhAgentMenu(event)" title="Клонировать и открыть в любом агенте как в Файлах">📂 Открыть в агенте</button>
               <div class="apply-menu" id="gh-agent-menu"></div>
             </div>
             <button class="btn btn-sm" onclick="ghOpenOnGithub()" title="Открыть на github.com в браузере (🖥)">🌐</button>
           </div>
           <div style="display:flex;gap:4px;margin-bottom:12px;flex-wrap:wrap">
             <button class="btn btn-sm gh-tab on" onclick="ghShowTab('contents',this)">📁 Файлы</button>
             <button class="btn btn-sm gh-tab" onclick="ghShowTab('branches',this)">🌿 Ветки</button>
             <button class="btn btn-sm gh-tab" onclick="ghShowTab('commits',this)">📝 Коммиты</button>
             <button class="btn btn-sm gh-tab" onclick="ghShowTab('workflows',this)">⚙ Workflows</button>
             <button class="btn btn-sm gh-tab" onclick="ghShowTab('runs',this)">🚀 Сборки</button>
             <button class="btn btn-sm gh-tab" onclick="ghShowTab('releases',this)">📦 Релизы</button>
           </div>
           <div id="gh-repo-contents"></div>
           <div id="gh-repo-branches" style="display:none"></div>
           <div id="gh-repo-commits" style="display:none"></div>
           <div id="gh-repo-workflows" style="display:none"></div>
           <div id="gh-repo-runs" style="display:none"></div>
           <div id="gh-repo-releases" style="display:none"></div>
         </div>
       </div>
     </div>
   </div>

