       <div style="margin-bottom:10px"><label style="font-size:12px;color:var(--t2)">Сообщение коммита</label><input type="text" id="gitfm-msg" style="width:100%;padding:10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;margin-top:4px"></div>
       <div style="margin-bottom:10px"><label style="font-size:12px;color:var(--t2)">Ветка для push (пусто = текущая)</label><input type="text" id="gitfm-branch" value="main" style="width:100%;padding:10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;margin-top:4px"></div>
       <div style="margin-bottom:10px"><label style="font-size:12px;color:var(--t2)">URL репозитория для push (если нет origin)</label><input type="text" id="gitfm-remote" placeholder="https://github.com/user/repo.git" style="width:100%;padding:10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;margin-top:4px"></div>
       <div id="gitfm-out" style="font-size:13px;color:var(--t2);margin-bottom:4px;white-space:pre-wrap;word-break:break-all;max-height:120px;overflow:auto"></div>
