   </div>

   <!-- Add Storage Modal -->
   <div class="modal-bg" id="modal-addstorage">
     <div class="modal">
       <h2>Добавить хранилище</h2>
       <div style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap">
         <button class="btn storage-type-btn on" data-type="adb" onclick="setStorageType('adb')">📱 ADB</button>
         <button class="btn storage-type-btn" data-type="ftp" onclick="setStorageType('ftp')">📂 FTP</button>
         <button class="btn storage-type-btn" data-type="gdrive" onclick="setStorageType('gdrive')">☁️ Drive</button>
         <button class="btn storage-type-btn" data-type="github" onclick="setStorageType('github')">🐙 GitHub</button>
         <button class="btn storage-type-btn" data-type="http" onclick="setStorageType('http')">🌐 HTTP</button>
         <button class="btn storage-type-btn" data-type="webdav" onclick="setStorageType('webdav')">📁 WebDAV</button>
       </div>
