     await pulseRun('pulseaudio --start --disallow-exit --exit-idle-time=-1 2>&1');
     res.json({ ok: true });
   } catch (e) { res.json({ ok: false, error: e.message }); }
 });

 app.post('/api/pulse/stop', async (req, res) => {
